renderLinks(){const grid=document.getElementById('linksGrid');if(!grid)return;grid.innerHTML='';const d=this.linksData;if(!d||d.length<2){grid.innerHTML='<p style="text-align:center;color:#888;padding:30px;">لا توجد بيانات</p>';return}let th='<div class="table-wrapper desktop-table"><table><thead><tr><th>ت</th><th>الاسم</th><th>النوع</th><th>الغاية والهدف</th><th>الاعضاء</th><th>رابط الانضمام</th></tr></thead><tbody>';let ch='<div class="mobile-cards">';for(let i=1;i<d.length;i++){const row=d[i];if(!row||!row[1]||!row[1].trim())continue;const seq=row[0]||'',nm=row[1]||'',tp=row[2]||'',pp=row[3]||'',mb=row[4]||'',lk=row[5]||'';th+=`<tr><td style="font-weight:700;color:#667eea;">${seq}</td><td><strong>${nm}</strong></td><td>${tp}</td><td>${pp}</td><td>${mb}</td><td>${this.formatLink(lk)}</td></tr>`;ch+=`<div class="link-card"><span style="font-size:11px;color:var(--text-secondary);">#${seq}</span><div class="link-title"><span class="link-label">الاسم:</span> ${nm}</div>${tp?`<div><span class="link-label">النوع:</span> <span class="link-type">${tp}</span></div>`:''}${pp?`<div class="link-desc"><span class="link-label">الغاية والهدف:</span> ${pp}</div>`:''}${mb?`<div class="link-members"><span class="link-label">الاعضاء:</span> ${mb}</div>`:''}<div style="margin-top:8px;"><span class="link-label">رابط الانضمام:</span> ${this.formatLink(lk)}</div></div>`}th+='</tbody></table></div>';ch+='</div>';grid.innerHTML=th+ch}
renderQA(){const container=document.getElementById('qaContainer');if(!container)return;container.innerHTML='';const d=this.qaData;if(!d||d.length<2){container.innerHTML='<p style="text-align:center;color:#888;padding:30px;">لا توجد أسئلة وأجوبة بعد.</p>';return}const qi=[];for(let i=1;i<d.length;i++){const row=d[i];if(!row||row.length<2)continue;const cat=(row[1]||'').trim(),q=(row[2]||'').trim(),a=(row[3]||'').trim();if(!q||!a||q==='السؤال'||q==='التصنيف'||cat==='التصنيف')continue;qi.push({category:cat||'عام',question:q,answer:a})}if(!qi.length){container.innerHTML='<p style="text-align:center;color:#888;padding:30px;">لا توجد أسئلة وأجوبة بعد.</p>';return}const cats={};qi.forEach(item=>{const c=item.category;if(!cats[c])cats[c]=[];cats[c].push(item)});let h='';Object.keys(cats).sort().forEach(cat=>{h+=`<div class="qa-category-section"><button class="qa-category-header open" onclick="toggleQACategory(this)"><span><i class="fas fa-folder"></i> ${cat} (${cats[cat].length})</span><i class="fas fa-chevron-down"></i></button><div class="qa-category-content show">`;cats[cat].forEach(item=>{h+=`<div class="qa-card"><div class="qa-card-header" onclick="toggleQACard(this.parentElement)"><span class="qa-category-tag">${item.category}</span><span class="qa-question-text">${item.question}</span><i class="fas fa-chevron-down qa-toggle-icon"></i></div><div class="qa-answer">${item.answer}</div></div>`});h+='</div></div>'});container.innerHTML=h;this.filterQA(document.getElementById('qaSearch')?.value||'')}
