parseOncallData(d){this.oncRows=[];this.oncHeaders=[];if(!d||d.length<2)return;
const rawHeaders=d[0]||[];
const firstDataRow=d[1]||[];
const isHeaderRow=firstDataRow&&(firstDataRow[0]||'').trim()==='اليوم'&&(firstDataRow[1]||'').includes('Date');
const startIdx=isHeaderRow?2:1;
const headerRow=d[0]||[];
const hasLabels=headerRow.some(h=>h&&h.length>0);
if(hasLabels){this.oncHeaders=headerRow}else{this.oncHeaders=rawHeaders}
document.getElementById('oncallMonthTitle').textContent=this.currentDisplayMonth+1;
for(let i=startIdx;i<d.length;i++){const row=d[i];if(!row||!row.length)continue;
let ds=row[1]||'';
if(!ds)ds=row[0]||'';
const dm=ds.match(/Date\((\d+),\s*(\d+),\s*(\d+)\)/);
if(dm){ds=`${parseInt(dm[1])}-${String(parseInt(dm[2])+1).padStart(2,'0')}-${String(parseInt(dm[3])).padStart(2,'0')}`}else{ds=extractDate(ds)||''}
if(ds)this.oncRows.push({date:ds,day:row[0]||'',row:row})}}
getOncRow(ds){return this.oncRows.find(r=>r.date===ds)||null}
