changeMonth(){this.currentDisplayMonth=parseInt(document.getElementById('monthSelector').value);const yr=parseInt(this.today.split('-')[0]);document.getElementById('oncallDatePicker').value=`${yr}-${String(this.currentDisplayMonth+1).padStart(2,'0')}-01`;document.getElementById('oncallMonthTitle').textContent=this.currentDisplayMonth+1;this.renderMonthlyCalendar();document.getElementById('oncallDayDisplay').innerHTML=''}
selectDayFromCalendar(){const v=document.getElementById('oncallDatePicker').value;if(v){const m=parseInt(v.split('-')[1])-1;if(m!==this.currentDisplayMonth){this.currentDisplayMonth=m;document.getElementById('monthSelector').value=m;document.getElementById('oncallMonthTitle').textContent=m+1;this.renderMonthlyCalendar()}this.showOncallDate(v);setTimeout(()=>{const el=document.getElementById('oncallDayDisplay');if(el)el.scrollIntoView({behavior:'smooth',block:'start'})},200)}}
showOncallDate(ds){const dp=document.getElementById('oncallDayDisplay');const dstr=ds||this.today;if(!dstr||!dp||!this.oncRows.length)return;const oncRow=this.getOncRow(dstr);if(!oncRow){dp.innerHTML=`<div class="oncall-day-card"><h3><i class="fas fa-calendar-day"></i> ${dstr} - ${getDayName(dstr)}</h3><p style="color:#888;">لا توجد مناوبات لهذا التاريخ.</p></div>`;return}const now=new Date();const ts=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')} ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}:${String(now.getSeconds()).padStart(2,'0')}`;const cats={};for(let col=2;col<this.oncHeaders.length;col++){const cn=this.oncHeaders[col]||'أخرى';const cc=(oncRow.row[col]||'').trim();if(!cc)continue;const names=splitNames(cc);if(!names.length)continue;if(!cats[cn])cats[cn]=[];for(const n of names){const resident=this.findRbyExact(n);const fn=resident?resident.name:n;const ph=resident?resident.phone:'';const ab=resident?resident.abbr:n;if(!cats[cn].find(x=>x.abbr===ab))cats[cn].push({abbr:ab,name:fn,phone:ph,resAbbr:ab})}}const dn=getDayName(dstr);const we=isWeekend(dstr);const catEntries=Object.entries(cats);const catCount=catEntries.length;const totalDoctors=catEntries.reduce((a,[,n])=>a+n.length,0);let h=`<div class="oncall-day-card" id="oncallCardContent"><div class="oncall-card-head"><h3 class="${we?'weekend':''}"><i class="fas fa-calendar-day"></i> ${dstr} - ${dn}${we?' <span class="day-badge weekend">عطلة</span>':''}</h3><div class="oncall-card-stats"><span class="oncall-stat-pill"><i class="fas fa-layer-group"></i> ${catCount} فئة</span><span class="oncall-stat-pill"><i class="fas fa-user-doctor"></i> ${totalDoctors} طبيب</span></div></div><div class="capture-timestamp"><i class="fas fa-clock"></i> ${ts}</div>`;if(!catCount)h+='<p style="color:#888;">لا توجد مناوبات مسجلة لهذا التاريخ.</p>';else{h+='<div class="oncall-categories-grid">';for(const[cn,names]of catEntries){h+=`<div class="oncall-category"><h4><span>${cn}</span><span class="cat-count">${names.length}</span></h4><div class="oncall-names-list">`;for(const n of names)h+=`<span class="oncall-name-tag">${mcn(n.name,n.phone,n.resAbbr)}</span>`;h+='</div></div>'}h+='</div>'}h+=`<div class="oncall-export-actions"><button class="download-btn" onclick="app.downloadOncallImage(false,this)"><i class="fas fa-camera btn-icon"></i><span class="btn-spinner"></span> تحميل المناوبات (عادي)</button><button class="download-btn hq-btn" onclick="app.downloadOncallImage(true,this)"><i class="fas fa-wand-magic-sparkles btn-icon"></i><span class="btn-spinner"></span> تحميل المناوبات (دقة فائقة)</button></div></div>`;dp.innerHTML=h}
setDownloadBtnState(btn,loading){if(!btn)return;btn.classList.toggle('loading',loading);btn.disabled=!!loading}
async _captureImage(el,fn,bg,btn,mode='normal'){if(this._id)return;this._id=true;this.setDownloadBtnState(btn,true);showDownloadProgress('جاري توليد الصورة...');updateDownloadProgress(5);let stage=null;try{await new Promise(requestAnimationFrame);const isOncall=el.id==='oncallCardContent';const isHQ=isOncall&&mode==='hq';const baseW=isOncall?840:920;const dpr=Math.max(1,window.devicePixelRatio||1);const sc=isHQ?Math.min(3.6,Math.max(2.85,dpr*1.35)):(isOncall?Math.min(3.0,Math.max(2.35,dpr*1.2)):Math.min(2.95,Math.max(2.2,dpr*1.2)));stage=document.createElement('div');stage.style.position='fixed';stage.style.left='-10000px';stage.style.top='0';stage.style.zIndex='-1';stage.style.pointerEvents='none';const capNode=el.cloneNode(true);capNode.classList.add('capture-mode');capNode.style.width=baseW+'px';capNode.style.maxWidth=baseW+'px';capNode.style.margin='0';stage.appendChild(capNode);document.body.appendChild(stage);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));updateDownloadProgress(14);const canvas=await html2canvas(capNode,{backgroundColor:bg,scale:sc,useCORS:true,allowTaint:true,logging:false});updateDownloadProgress(62);const pd=isOncall?20:22;const nc=document.createElement('canvas');nc.width=canvas.width+pd*2;nc.height=canvas.height+pd*2;let ctx=nc.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,nc.width,nc.height);ctx.drawImage(canvas,pd,pd);const maxSide=isHQ?3400:(isOncall?2850:3500);const side=Math.max(nc.width,nc.height);let outCanvas=nc;if(side>maxSide){const ratio=maxSide/side;outCanvas=document.createElement('canvas');outCanvas.width=Math.round(nc.width*ratio);outCanvas.height=Math.round(nc.height*ratio);const octx=outCanvas.getContext('2d');octx.imageSmoothingEnabled=true;octx.imageSmoothingQuality='high';octx.drawImage(nc,0,0,outCanvas.width,outCanvas.height)}updateDownloadProgress(86);const blob=await new Promise(res=>outCanvas.toBlob(res,'image/png'));if(!blob)throw new Error('PNG export failed');const url=URL.createObjectURL(blob);const link=document.createElement('a');link.download=fn;link.href=url;document.body.appendChild(link);link.click();document.body.removeChild(link);setTimeout(()=>URL.revokeObjectURL(url),1500);updateDownloadProgress(100);setTimeout(()=>{hideDownloadProgress();this._id=false;this.setDownloadBtnState(btn,false);showToast(isHQ?'تم التحميل بدقة فائقة!':'تم التحميل بجودة عالية وبحجم أنسب للمشاركة!')},450)}catch(e){console.error(e);hideDownloadProgress();this._id=false;this.setDownloadBtnState(btn,false);showToast('تعذر توليد الصورة. حاول مرة أخرى.')}finally{if(stage&&stage.parentNode)stage.parentNode.removeChild(stage)}}
downloadOncallImage(hq=false,triggerBtn=null){const el=document.getElementById('oncallCardContent');if(!el)return;const btn=triggerBtn||el.querySelector('.download-btn');const bg=document.body.classList.contains('dark-mode')?'#1e293b':'#ffffff';this._captureImage(el,`مناوبات_${document.getElementById('oncallDatePicker').value||this.today}.png`,bg,btn,hq?'hq':'normal')}
